{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--accent:#9be7e7;--muted:#98a3ad;--glass:rgba(255,255,255,0.04)}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;color:#e6f7f7;background:radial-gradient(1200px 600px at 10% 10%, rgba(12,18,24,0.6), transparent), linear-gradient(180deg, #051018 0%, #08121a 100%);min-height:100vh}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,#0b3a3a,#062f2f);display:grid;place-items:center;color:var(--accent);font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:14px}
    main{max-width:980px;margin:24px auto;padding:28px;background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);border-radius:14px;box-shadow:0 6px 30px rgba(2,6,10,0.6)}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:22px;align-items:start}
    h1{margin:0 0 8px 0;color:#dff7f7;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .side-card{background:var(--card);padding:18px;border-radius:12px;color:#dff7f7}
    .pattern{height:96px;border-radius:10px;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="400" height="120" viewBox="0 0 400 120"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="%2300a9a9" stop-opacity="0.2"/><stop offset="1" stop-color="%23007f7f" stop-opacity="0.05"/></linearGradient></defs><rect width="400" height="120" fill="%230a1216"/><g fill="none" stroke="%2300d2d2" stroke-opacity="0.08" stroke-width="2"><path d="M0 80 C50 40, 120 40, 170 80 C220 120, 300 120, 400 80"/></g><g opacity="0.12"><circle cx="40" cy="30" r="18" fill="url(%23g)"/><circle cx="320" cy="80" r="22" fill="url(%23g)"/></g></svg>');background-size:cover}
    .grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}
    .card{background:var(--glass);padding:16px;border-radius:10px;color:#eafdfd}
    .muted{color:var(--muted);font-size:14px}
    footer{padding:22px;text-align:center;color:var(--muted)}
    /* small utilities */
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:rgba(155,231,231,0.06);color:var(--accent);font-weight:600;font-size:13px}
    .cta-btn{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#01292f;text-decoration:none;font-weight:700}
    .disclaimer{font-size:13px;color:#c7eaea;margin-top:12px}
    @media (max-width:880px){.hero{grid-template-columns:1fr;}.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div style="line-height:1">
        <div style="font-weight:700;color:#dff7f7">{{BUSINESS_NAME}}</div>
        <div class="muted">Studio in {{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Site">
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Fees</a>
      <a href="about.html">Studio</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <h1>We hold space with sound — simple, curated, and ceremonial</h1>
        <p class="lead">Sound sessions that sit somewhere between a guided rest and a shared ritual. We meet in small cohorts, where layered tones support curiosity, rest, and realignment.</p>
        <div class="grid">
          <div class="card">
            <div style="font-weight:700">Our approach</div>
            <p class="muted">We combine tuned bowls, breath-led pauses, and guided anchors so the group travels a shared arc — warm arrival, eased middle, gentle re-entry.</p>
          </div>
          <div class="card">
            <div style="font-weight:700">Cohorts & series</div>
            <p class="muted">Most people find a short cohort (3–6 sessions) is a sweet balance: communal rhythm plus time to notice change between gatherings.</p>
          </div>
        </div>
      </div>

      <aside class="side-card">
        <div class="pattern" aria-hidden="true"></div>
        <div style="margin-top:12px;font-weight:700">Next cohort starts soon</div>
        <div class="muted">Join a small-series that meets weekly — gentle pacing, shared learning.</div>
        <a class="cta-btn" href="book.html">See cohort dates</a>
      </aside>
    </section>

    <section style="margin-top:22px">
      <h2 style="color:#dff7f7;margin-bottom:8px">Why sound, why together?</h2>
      <p class="muted">Sound works on the edges of cognition: it helps soften the tightness around thoughts and makes breathing less effortful. In cohorts, people notice new perspectives appear between sessions — small shifts that compound.</p>

      <div class="grid" style="margin-top:14px">
        <div class="card">
          <div style="font-weight:700">Attunement</div>
          <p class="muted">We curate tonal journeys that guide attention away from pressure and toward ease: not about doing it right, but about coming along.</p>
        </div>
        <div class="card">
          <div style="font-weight:700">Structure</div>
          <p class="muted">Each session has an arrival check-in, a central sound arc, and a short integration to help transfer the felt shift to the week ahead.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:22px">
      <h2 style="color:#dff7f7;margin-bottom:8px">Contraindications and safety</h2>
      <p class="muted">Sound baths are deeply restorative for many people, but they are not right for everyone. If you have an implanted medical device (e.g., pacemaker), are pregnant and experiencing complications, have uncontrolled epilepsy, or severe psychiatric conditions that include recent psychosis or active suicidal ideation, please contact us before booking. We will help you choose a safe format — private, adjusted, or recommend clinical care when needed.</p>
    </section>

    <section style="margin-top:22px">
      <h2 style="color:#dff7f7;margin-bottom:8px">Meet the team</h2>
      <div class="grid">
        <div class="card">
          <div style="font-weight:700">Lead facilitator</div>
          <p class="muted">A blend of somatic training and group facilitation. Focused on pacing and accessible entry points for everyone.</p>
        </div>
        <div class="card">
          <div style="font-weight:700">Guest musicians</div>
          <p class="muted">Occasional collaborators bring harp, voice, and subtle electronics to broaden the sonic palette.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:22px;display:flex;gap:14px;align-items:center;flex-wrap:wrap">
      <div style="flex:1">
        <div style="font-weight:700;color:#dff7f7">Ready to explore?</div>
        <div class="muted" style="margin-top:6px">Try a single gathering, or reserve a spot in the next small-series cohort.</div>
      </div>
      <div>
        <a class="cta-btn" href="book.html">Reserve a seat — new cohorts</a>
      </div>
    </section>

  </main>

  <footer>
    <div class="muted">Questions? <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a> — Or call <span style="color:var(--accent)">{{PHONE}}</span></div>
    <div style="margin-top:8px" class="muted">© <span id="year"></span> {{BUSINESS_NAME}} — Small cohorts, spacious listening</div>
  </footer>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#071a1a;--accent:#8ae1df;--muted:#9fb6b6}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial;background:linear-gradient(180deg,#031014 0%,#071018 100%);color:#e8f9f9;min-height:100vh}
    header{display:flex;justify-content:space-between;padding:18px 24px;align-items:center}
    .logo{width:48px;height:48px;border-radius:8px;background:linear-gradient(135deg,#093435,#073a3a);display:grid;place-items:center;font-weight:700;color:var(--accent)}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px;font-size:14px}
    main{max-width:980px;margin:18px auto;padding:22px}
    h1{margin:0 0 6px 0;color:#dff7f7}
    .faq-list{margin-top:12px}
    .qa{background:rgba(255,255,255,0.02);padding:14px;border-radius:10px;margin-bottom:10px}
    .q{display:flex;justify-content:space-between;align-items:center;cursor:pointer}
    .q h3{margin:0;font-size:16px}
    .a{margin-top:8px;color:var(--muted);display:none}
    .pill{background:rgba(138,225,223,0.06);padding:6px 10px;border-radius:999px;color:var(--accent);font-weight:700}
    .search{margin-top:12px;display:flex;gap:10px}
    .search input{flex:1;padding:10px;border-radius:10px;border:0;background:rgba(255,255,255,0.02);color:#dff7f7}
    .cta{margin-top:18px}
    .cta a{background:var(--accent);color:#002a2a;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
    .alt{font-size:13px;color:var(--muted);margin-top:10px}
    footer{margin-top:28px;color:var(--muted);font-size:13px}
    @media (max-width:780px){header{flex-direction:column;align-items:flex-start}nav{margin-top:12px}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="color:var(--muted);font-size:13px">Sound gatherings in {{CITY}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <h1>Frequently asked questions</h1>
    <p class="alt">Short answers here; if something feels unclear, email <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a> or call <span style="color:var(--accent)">{{PHONE}}</span>.</p>

    <div class="search">
      <input id="search" placeholder="Search the FAQ..." aria-label="Search FAQ">
      <button id="clear" style="padding:10px;border-radius:10px;background:rgba(255,255,255,0.02);color:var(--muted);border:0">Clear</button>
    </div>

    <div class="faq-list" id="faqs">
      <div class="qa" data-tags="arrival what-to-bring">
        <div class="q"><h3>What should I bring?</h3><span class="pill">Practical</span></div>
        <div class="a">A yoga mat or blanket, a small pillow for comfort, and water. Wear layers — we dim the room and some people feel cool during deep rest.</div>
      </div>

      <div class="qa" data-tags="noise-sensitivity medical">
        <div class="q"><h3>Are the sounds loud?</h3><span class="pill">Safety</span></div>
        <div class="a">We work with tuned bowls and gentle resonances designed to be felt more than heard. If you are sensitive to vibration, tell the facilitator before we begin — we can adapt placement or offer ear covers.</div>
      </div>

      <div class="qa" data-tags="cancellations payments">
        <div class="q"><h3>What's the cancellation policy?</h3><span class="pill">Booking</span></div>
        <div class="a">For single gatherings, cancellations up to 48 hours before the session receive a full refund. Cohort commitments have different terms listed at booking; contact us at {{EMAIL}} for details.</div>
      </div>

      <div class="qa" data-tags="health contraindications safety">
        <div class="q"><h3>Are there contraindications?</h3><span class="pill">Health</span></div>
        <div class="a">If you have an implanted medical device, active uncontrolled epilepsy, or significant acute psychiatric symptoms, please consult with us before booking. Pregnant people with complications should check with their provider. We can offer private or modified sessions to make participation safer.</div>
      </div>

      <div class="qa" data-tags="children groups age">
        <div class="q"><h3>Can children attend?</h3><span class="pill">Logistics</span></div>
        <div class="a">Our gatherings are sized for adults. For family-friendly offerings, check the Events calendar for special sessions or contact us about private bookings.</div>
      </div>

    </div>

    <div class="cta">
      <a href="book.html">Reserve a spot — pick a mood</a>
      <div class="alt">Prefer to talk? Call {{PHONE}} or write to <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a>.</div>
    </div>

  </main>

  <footer style="padding:18px 24px;text-align:center;color:var(--muted)">
    © <span id="y"></span> {{BUSINESS_NAME}} — Small cohorts, careful listening
  </footer>

  <script>
    document.getElementById('y').textContent = new Date().getFullYear();
    // Toggle answers
    document.querySelectorAll('.qa').forEach(node=>{
      const header = node.querySelector('.q');
      header.addEventListener('click', ()=>{
        const a = node.querySelector('.a');
        const open = a.style.display === 'block';
        document.querySelectorAll('.a').forEach(x=>x.style.display='none');
        a.style.display = open? 'none':'block';
      });
    });

    // Simple search
    const search = document.getElementById('search');
    const clear = document.getElementById('clear');
    search.addEventListener('input', ()=>{
      const q = search.value.trim().toLowerCase();
      document.querySelectorAll('.qa').forEach(item=>{
        const text = (item.textContent||'').toLowerCase();
        item.style.display = text.includes(q)?'block':'none';
      });
    });
    clear.addEventListener('click', ()=>{search.value='';search.dispatchEvent(new Event('input'))});
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071316;--panel:#072226;--accent:#8ef0e6;--muted:#9cc3c1}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#031212 0%,#071316 100%);color:#e9fcfb;min-height:100vh}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px}
    .logo{width:52px;height:52px;border-radius:8px;background:linear-gradient(135deg,#064343,#083737);display:grid;place-items:center;font-weight:800;color:var(--accent)}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px}
    main{max-width:980px;margin:20px auto;padding:18px}
    .hero{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:18px;border-radius:12px;display:flex;gap:18px;align-items:center}
    .hero .left{flex:1}
    .hero h1{margin:0 0 6px 0;color:#dff7f7}
    .controls{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
    .control{background:rgba(255,255,255,0.02);padding:10px;border-radius:10px}
    .mood-grid{display:flex;gap:8px}
    .mood{padding:8px 10px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.04);cursor:pointer}
    .mood.active{background:linear-gradient(90deg, rgba(142,240,230,0.12), rgba(142,240,230,0.04));border-color:rgba(142,240,230,0.22)}
    .slider{display:flex;gap:8px;align-items:center}
    .intensity button{padding:8px 10px;border-radius:8px;border:0;background:rgba(255,255,255,0.02);color:var(--muted);cursor:pointer}
    .intensity button.active{background:var(--accent);color:#012928}
    .panel{background:var(--panel);padding:16px;border-radius:12px}
    .recommend{font-weight:700;color:#dff7f7}
    .sub{color:var(--muted);font-size:14px}
    .prices{margin-top:12px;display:flex;gap:10px}
    .price{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;flex:1}
    .primary-cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#002a2a;text-decoration:none;font-weight:800}
    .safety{margin-top:12px;color:var(--muted);font-size:13px}
    .disclaimer{margin-top:10px;color:#cbeeea;font-size:13px}
    @media (max-width:780px){.hero{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="color:var(--muted);font-size:13px">Thoughtful sound gatherings in {{CITY}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="pricing.html">Fees</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="left">
        <h1>Reserve a seat or book a cohort</h1>
        <div class="sub">Choose how you arrive — the page adapts suggestions and the primary action to what you need right now.</div>

        <div class="controls">
          <div class="control">
            <div style="font-weight:700;margin-bottom:6px">Mood-to-Method</div>
            <div class="mood-grid" id="moods">
              <button class="mood" data-mood="ruffled">Ruffled</button>
              <button class="mood" data-mood="restless">Restless</button>
              <button class="mood" data-mood="heavy">Heavy</button>
              <button class="mood" data-mood="curious">Curious</button>
              <button class="mood" data-mood="celebrate">Celebratory</button>
            </div>
          </div>

          <div class="control">
            <div style="font-weight:700;margin-bottom:6px">Sound preference</div>
            <div class="slider intensity" id="intensity">
              <button data-int="gentle">Gentle</button>
              <button data-int="medium">Medium</button>
              <button data-int="intense">Intense</button>
            </div>
          </div>

          <div class="control">
            <div style="font-weight:700;margin-bottom:6px">Format</div>
            <div class="sub">Single gathering, cohort (4 weeks), or private session</div>
          </div>
        </div>

      </div>

      <aside class="panel">
        <div class="recommend" id="recTitle">Pick a mood to see a recommendation</div>
        <div class="sub" id="recBlurb" style="margin-top:6px">We’ll suggest program sizing and tone. Your choice changes the reserve button below.</div>

        <div class="prices" id="prices" aria-live="polite">
          <div class="price">
            <div style="font-weight:800">Drift</div>
            <div class="sub">Single gathering • 60–75 min</div>
            <div style="margin-top:8px;font-weight:700" id="p1">$30</div>
          </div>
          <div class="price">
            <div style="font-weight:800">Flow</div>
            <div class="sub">Cohort • 4 weekly sessions</div>
            <div style="margin-top:8px;font-weight:700" id="p2">$100</div>
          </div>
          <div class="price">
            <div style="font-weight:800">Haven</div>
            <div class="sub">Private • tailored</div>
            <div style="margin-top:8px;font-weight:700" id="p3">$150</div>
          </div>
        </div>

        <a id="primaryCta" class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>

        <div class="safety">We prioritize safety: if you have an implanted device, uncontrolled epilepsy, or active psychosis, contact us before booking. Pregnant folks with complications should speak with their provider.</div>
        <div class="disclaimer">Need help choosing? Call <strong>{{PHONE}}</strong> or email <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a>.</div>
      </aside>
    </section>

    <section style="margin-top:18px" class="panel">
      <div style="font-weight:800">How Mood-to-Method works</div>
      <p class="sub">Pick a feeling — the recommendation highlights the best format and nudges the sound palette. The intensity control tilts the program: gentle adds space and breath, medium adds melodic bowls, intense uses layered tones and longer resonances. Mixing these lets you find something that fits this moment.</p>
      <ul style="color:var(--muted)">
        <li>Ruffled + Gentle → Short arrival practice, soft bowls, grounding cohort seat.</li>
        <li>Heavy + Gentle → Longer settling, extra integration, recommended private or small cohort.</li>
        <li>Curious + Intense → Exploratory soundscapes, slight dynamic contrast, cohort format works well.</li>
      </ul>
    </section>

  </main>

  <footer style="padding:18px;color:var(--muted);text-align:center">Questions? <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a> • {{PHONE}}</footer>

  <script>
    // Mood-to-Method + Sound preference mixer
    const moodButtons = Array.from(document.querySelectorAll('.mood'));
    const intensityButtons = Array.from(document.querySelectorAll('.intensity button'));
    const recTitle = document.getElementById('recTitle');
    const recBlurb = document.getElementById('recBlurb');
    const primaryCta = document.getElementById('primaryCta');
    const price1 = document.getElementById('p1');
    const price2 = document.getElementById('p2');
    const price3 = document.getElementById('p3');

    let state = {mood:null,intensity:'medium'};

    const rules = {
      ruffled: {title:'Ease & regroup',blurb:'A short cohort or single session with emphasis on breath anchors and soft tones.'},
      restless: {title:'Calm focus',blurb:'Medium-length gatherings with rhythmic bowls to steady attention.'},
      heavy: {title:'Soft weight relief',blurb:'Slower pacing, extra integration. Consider private or small cohort.'},
      curious: {title:'Playful exploration',blurb:'A curious arc that invites noticing — great in cohort format.'},
      celebrate: {title:'Bright release',blurb:'Lively harmonics and shared closing. Cohort or special event recommended.'}
    };

    const basePrices = {gentle:{p1:28,p2:95,p3:140},medium:{p1:34,p2:110,p3:160},intense:{p1:45,p2:130,p3:200}};

    function updatePrices(){
      const tier = state.intensity || 'medium';
      price1.textContent = '$'+basePrices[tier].p1;
      price2.textContent = '$'+basePrices[tier].p2;
      price3.textContent = '$'+basePrices[tier].p3;
    }

    function updateRecommendation(){
      if(!state.mood){recTitle.textContent = 'Pick a mood to see a recommendation';recBlurb.textContent = 'We’ll suggest program sizing and tone.';primaryCta.textContent = '{{PRIMARY_CTA_LABEL}}';return}
      const r = rules[state.mood];
      recTitle.textContent = r.title + ' — ' + (state.intensity.charAt(0).toUpperCase()+state.intensity.slice(1));
      recBlurb.textContent = r.blurb + ' (Tone: ' + state.intensity + ')';
      // CTA changes depending on mood & intensity
      if(state.mood === 'heavy'){
        primaryCta.textContent = 'Request a private session';
        primaryCta.href = 'contact.html';
      } else if(state.mood === 'celebrate'){
        primaryCta.textContent = 'Join a communal gathering';
        primaryCta.href = 'events.html';
      } else {
