          primaryCta.textContent = 'Book the fuller sound arc';primaryCta.href='book.html?format=flow';
        } else {primaryCta.textContent = 'Save a spot in the next cohort';primaryCta.href='book.html?format=flow'}
      }
    }

    moodButtons.forEach(b=>{
      b.addEventListener('click', ()=>{
        moodButtons.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        state.mood = b.dataset.mood;
        updateRecommendation();
